    while cur:
        if cur in seen:
            # cycle: collect codes in cycle
            cyc=seen[seen.index(cur):]
            codes=[resolve(r)[0] for r in cyc]
            return ('CYCLE', cyc, codes)
        seen.append(cur)
        code,nxt=resolve(cur)
        if code: lastcode=code
        if not nxt:
