export const listDocumentKeys = async (
    Bucket: string,
    Prefix: string,
    credentials = undefined,
): Promise<Array<string>> => {
    const client = new S3Client(credentials ? { credentials } : {});
    const keys: Array<string> = [];
    let ContinuationToken: string;
