        ContinuationToken = response?.NextContinuationToken;
        (response?.Contents ?? []).forEach(({ Key }) => {
            if (Key && !Key.endsWith('/')) {
                keys.push(Key);
            }
        });
    } while (ContinuationToken);
    return keys;
